if(!window.pgToggleableRegistered){let e=()=>{window.Alpine.data(`pgToggleable`,e=>({field:e.field??null,tableName:e.tableName??null,enabled:e.enabled??!1,id:e.id,trueValue:e.trueValue,falseValue:e.falseValue,toggle:e.toggle,save(){this.toggle=+(this.toggle===0),this.$wire.dispatch(`pg:toggleable-`+this.tableName,{id:this.id,field:this.field,value:this.toggle})}}))};window.Alpine?e():document.addEventListener(`alpine:init`,()=>{e()}),window.pgToggleableRegistered=!0}